const char* cepas_station_name(const char* code) {
    if(!code) return NULL;
    for(size_t i = 0; i < sizeof(stations) / sizeof(stations[0]); i++) {
        if(strcmp(stations[i].code, code) == 0) return stations[i].name;
    }
    return NULL;
}
